      "op": "replace",
      "path": "/workflow/nodes/evaluate/code",
      "value": "import json, re, datetime
try:
    vars['engine_route'] = 'identity'
    vars['identity_instruction'] = 'I could not complete that step.'
    for key in ['collection_instruction', 'resolution_instruction', 'resolution_action', 'closing_instruction', 'security_field', 'security_answer', 'write_request']:
        vars[key] = ''
    vars['calendar_facts'] = []
    raw = vars.get('state_json', '{}')
    s = json.loads(raw) if isinstance(raw, str) else dict(raw)
    if not isinstance(s, dict):
        s = dict()
    defaults = dict(phase='name', verified=False, dob_ok=False, phone_ok=False, loaded=False, products=[], index=0, mode='all', wrong=0, declines=0, stops=0, human_asked=False, hardship=False, buffer='', month_word=False, invalid_callbacks=0, callback_date='', callback_time='', say='', notice=[], confirmed=False, transferred='', close_outcome='', close_reason='', action='', inflight=dict(), close_attempted=False, held_proposal=dict(), date_query=dict())
    for k, v in defaults.items():
        s.setdefault(k, v)
    entry_phase = s['phase']
    now = datetime.datetime.fromisoformat(str(vars.get('now', '')).replace('Z', '+00:00'))
    today = now.date()
    holidays = set(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
    weekdays = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
    months = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']
    def business(d):
        return d.weekday() < 5 and d.isoformat() not in holidays
    def following(d):
        d += datetime.timedelta(days=1)
        while not business(d):
            d += datetime.timedelta(days=1)
        return d
    def nth(n):
        d = today
        for unused in range(n):
            d = following(d)
        return d
    def spoken(d):
        if isinstance(d, str):
            d = datetime.date.fromisoformat(d)
        return str(d.day) + ' ' + months[d.month - 1].capitalize() + ' ' + str(d.year)
    def money(n):
        x = float(n)
        return str(int(x)) if x.is_integer() else str(x)
    def norm(t):
        return re.sub(r'[^a-z0-9]+', ' ', str(t).lower()).strip()
    def period_window(context):
        t = norm(context)
        monday = today - datetime.timedelta(days=today.weekday())
        if 'week after next' in t:
            start = monday + datetime.timedelta(days=14)
            return start, start + datetime.timedelta(days=6)
        if 'next week' in t or 'following week' in t:
            start = monday + datetime.timedelta(days=7)
            return start, start + datetime.timedelta(days=6)
        if 'this week' in t or 'current week' in t:
            return monday, monday + datetime.timedelta(days=6)
        if 'month' in t:
            start = today.replace(day=1)
            if 'next month' in t or 'following month' in t:
                start = (start.replace(day=28) + datetime.timedelta(days=4)).replace(day=1)
            elif not ('this month' in t or 'the month' in t or 'month end' in t or 'month s end' in t):
                return None
            end = (start.replace(day=28) + datetime.timedelta(days=4)).replace(day=1) - datetime.timedelta(days=1)
            return start, end
        return None
    def parse_date(text, kind, horizon, context=''):
        t = str(text).strip().lower()
        if not t or kind == 'period':
            return None
        t = re.sub(r'(\d)(st|nd|rd|th)\b', r'\1', t)
        if t == 'today':
            return today
        if t == 'tomorrow':
            return today + datetime.timedelta(days=1)
        if t in ['day after tomorrow', 'the day after tomorrow']:
            return today + datetime.timedelta(days=2)
        m = re.fullmatch(r'in (\d+) days?', t)
        if m:
            return today + datetime.timedelta(days=int(m.group(1)))
        if t in ['a week from today', 'one week from today']:
            return today + datetime.timedelta(days=7)
        m = re.fullmatch(r'(this|next) (monday|tuesday|wednesday|thursday|friday|saturday|sunday)', t)
        if m:
            monday = today - datetime.timedelta(days=today.weekday())
            return monday + datetime.timedelta(days=weekdays.index(m.group(2)) + (7 if m.group(1) == 'next' else 0))
        window = period_window(context)
        if t in weekdays:
            if not window:
                return None
            d = window[0]
            candidates = []
            while d <= window[1]:
                if d.weekday() == weekdays.index(t):
                    candidates.append(d)
                d += datetime.timedelta(days=1)
            return candidates[0] if len(candidates) == 1 else None
        try:
            if re.fullmatch(r'\d{4}-\d{2}-\d{2}', t):
                return datetime.date.fromisoformat(t)
            nums = re.findall(r'\d+', t)
            if re.fullmatch(r'\d{1,2}[./-]\d{1,2}[./-]\d{4}', t):
                return datetime.date(int(nums[2]), int(nums[1]), int(nums[0]))
            mi = [i + 1 for i, name in enumerate(months) if re.search(r'\b' + name + r'\b', t)]
            candidates = []
            lo, hi = window if window else (today, horizon)
            if mi and nums:
                years = [int(nums[1])] if len(nums) == 2 and len(nums[1]) == 4 else sorted(set([lo.year, hi.year]))
                for year in years:
                    try:
                        d = datetime.date(year, mi[0], int(nums[0]))
                        if len(nums) == 2 or lo <= d <= hi:
                            candidates.append(d)
                    except Exception:
                        pass
            elif len(nums) == 1 and re.fullmatch(r'(?:the )?\d{1,2}', t):
                d = lo
                while d <= hi:
                    if d.day == int(nums[0]):
                        candidates.append(d)
                    d += datetime.timedelta(days=1)
            elif re.fullmatch(r'\d{1,2}[./-]\d{1,2}', t):
                for year in sorted(set([lo.year, hi.year])):
                    try:
                        d = datetime.date(year, int(nums[1]), int(nums[0]))
                        if lo <= d <= hi:
                            candidates.append(d)
                    except Exception:
                        pass
            return candidates[0] if len(candidates) == 1 else None
        except Exception:
            return None
    def end(outcome, reason, message=''):
        s['close_outcome'] = outcome
        s['close_reason'] = reason
        s['phase'] = 'final'
        if message:
            s['notice'].append(message)
    def transfer(queue):
        s['action'] = 'transfer_to_agent'
        s['transfer_request'] = queue
        s['phase'] = 'resolve'
        s['confirmed'] = False
        for p in s['products']:
            if p['status'] == 'pending':
                p['status'] = 'abandoned'
    def selection(scope):
        text = norm(scope)
        ps = s['products']
        if text in ['all', 'everything', 'all of them', 'all products', 'both', 'all three']:
            return [i for i, p in enumerate(ps) if p['status'] != 'recorded']
        if not text:
            if s['date_query']:
                return list(s['date_query']['indices'])
            if s['phase'] == 'confirm':
                return [i for i, p in enumerate(ps) if p['status'] == 'pending']
            return [s['index']] if s['mode'] == 'product' else list(range(len(ps)))
        if text in ['current', 'this one', 'that one', 'it']:
            return [s['index']] if s['mode'] == 'product' else list(range(len(ps)))
        text = re.sub(r'^(?:(?:my|the|that|this|your) )+', '', text)
        text = re.sub(r' (?:payment|account)$', '', text)
        found = []
        for i, p in enumerate(ps):
            aliases = [norm(p['product_id']), norm(p['label']), norm(p['type'])]
            if p['type'] == 'credit_card':
                suffix = str(p.get('card_last4', ''))
                aliases += ['card', 'credit card', suffix, 'card ending ' + suffix, 'credit card ending ' + suffix]
            elif p['type'] == 'personal_loan':
                aliases += ['personal', 'personal loan', 'loan']
            else:
                aliases += ['car', 'auto', 'car loan', 'auto loan', 'loan']
            if text in aliases:
                found.append(i)
        return found if len(found) == 1 else []
    def readback():
        pending = [p for p in s['products'] if p['status'] == 'pending']
        s['phase'] = 'confirm'
        s['confirmed'] = False
        s['date_query'] = dict()
        s['say'] = 'Please confirm: ' + '; '.join(p['label'] + ', ' + money(p['amount']) + ', on ' + spoken(p['date']) for p in pending) + '. Do you confirm?'
    def progress():
        opens = [i for i, p in enumerate(s['products']) if p['status'] == 'open']
        if opens:
            s['index'] = opens[0]
            s['mode'] = 'product'
            s['phase'] = 'collect'
            if s['hardship']:
                s['phase'] = 'hardship'
                s['say'] = 'Would you like me to connect you with our customer support team?'
            else:
                persuade(opens[0])
        elif any(p['status'] == 'pending' for p in s['products']):
            readback()
        else:
            s['phase'] = 'final'
    def persuade(i):
        p = s['products'][i]
        if s['hardship']:
            s['phase'] = 'hardship'
            s['say'] = 'Would you like me to connect you with our customer support team?'
            return
        step = max(int(p.get('attempt_step', 0)), int(p['attempts']))
        while step < p['budget']:
            step += 1
            p['attempt_step'] = step
            amount = p['floor'] if p['too_much'] or step == 2 else p['past_due']
            day = p['deadline'] if step == 2 else p['offer_day']
            key = money(amount) + '|' + day
            if key in p['rejected']:
                continue
            p['attempts'] += 1
            p['offered_amount'] = amount
            p['offered_date'] = day
            p['offer_type'] = 'persuasion'
            if amount == p['floor']:
                p['floor_offered'] = True
            s['phase'] = 'collect'
            s['mode'] = 'product'
            s['index'] = i
            s['say'] = 'Can you pay ' + money(amount) + ' for your ' + p['label'] + ' on ' + spoken(day) + '?'
            if amount < p['past_due']:
                s['say'] = 'The rest will remain overdue. ' + s['say']
            return
        p['status'] = 'done'
        p['reason'] = 'refused'
        progress()
    def remember_rejection(p):
        day = p.get('date') if p['status'] == 'pending' else p.get('offered_date')
        amount = p.get('amount') if p['status'] == 'pending' else p.get('offered_amount')
        if day and amount is not None:
            key = money(amount) + '|' + day
            if key not in p['rejected']:
                p['rejected'].append(key)
    def reject(i):
        p = s['products'][i]
        remember_rejection(p)
        p['status'] = 'open'
        persuade(i)
    def offer_adjustment(i, amount, day, message, offer_type):
        p = s['products'][i]
        p['offered_amount'] = amount
        p['offered_date'] = day
        p['offer_type'] = offer_type
        p['status'] = 'open'
        s['confirmed'] = False
        s['index'] = i
        s['mode'] = 'product'
        s['phase'] = 'collect'
        s['say'] = message + ' Can you pay ' + money(amount) + ' for your ' + p['label'] + ' on ' + spoken(day) + '?'
    event = str(vars.get('bank_event', ''))
    vars['bank_event'] = ''
    unavailable = (entry_phase == 'verifying' and vars.get('security_status') == 'unavailable') or (entry_phase == 'loading' and vars.get('account_status') == 'unavailable') or (entry_phase == 'recording' and vars.get('promise_status') == 'unavailable')
    if unavailable:
        s['phase'] = 'service_wait'
        s['say'] = 'I could not confirm the result of that operation.'
    if event == 'account' and s['verified'] and str(vars.get('account_status', '')) == 'loaded':
        raw_products = vars.get('account_products', [])
        if isinstance(raw_products, str):
            raw_products = json.loads(raw_products)
        if not isinstance(raw_products, list) or not raw_products:
            raw_products = []
            for i in range(3):
                base = 'lookup_response.data.products.' + str(i) + '.'
                item = dict()
                for field in ['product_id', 'type', 'card_last4', 'past_due', 'days_late', 'minimum_payment', 'instalment_amount']:
                    if base + field in vars:
                        item[field] = vars[base + field]
                if item:
                    raw_products.append(item)
        if not 1 <= len(raw_products) <= 3:
            raise ValueError('invalid account')
        friday = today - datetime.timedelta(days=today.weekday()) + datetime.timedelta(days=4)
        while not business(friday):
            friday -= datetime.timedelta(days=1)
        if friday <= today:
            friday = today - datetime.timedelta(days=today.weekday()) + datetime.timedelta(days=11)
            while not business(friday):
                friday -= datetime.timedelta(days=1)
        ps = []
        for item in raw_products:
            p = dict(item)
            late = int(p['days_late'])
            if not 1 <= late <= 45 or p['type'] not in ['credit_card', 'personal_loan', 'car_loan']:
                raise ValueError('invalid product')
            p['past_due'] = float(p['past_due'])
            p['floor'] = float(p['minimum_payment'] if p['type'] == 'credit_card' else p['instalment_amount'])
            if not 0 < p['floor'] <= p['past_due']:
                raise ValueError('invalid amounts')
            p['label'] = 'credit card ending ' + str(p['card_last4']) if p['type'] == 'credit_card' else p['type'].replace('_', ' ')
            p['deadline'] = nth(12 if late <= 7 else 7).isoformat()
            p['offer_day'] = min(friday, datetime.date.fromisoformat(p['deadline'])).isoformat()
            p['band'] = 'early' if late <= 7 else 'late'
            p['budget'] = 1 if late <= 7 else 2
            p.update(dict(status='open', reason='', attempts=0, attempt_step=0, write_attempts=0, too_much=False, floor_offered=False, date_clarifications=0, rejected=[], amount=p['past_due'], date='', noted=False))
            ps.append(p)
        if len(set(p['product_id'] for p in ps)) != len(ps):
            raise ValueError('duplicate products')
        s['products'] = ps
        s['loaded'] = True
        s['phase'] = 'collect'
        s['mode'] = 'all'
        s['index'] = 0
        s['say'] = 'I am calling from the collections team about a late payment. ' + ' '.join('Your ' + p['label'] + ' has a past-due amount of ' + money(p['past_due']) + ' and is ' + str(p['days_late']) + ' days late.' for p in ps)
        s['say'] += ' Can you make this payment today?' if len(ps) == 1 else ' Can you make all of these payments today?'
    neutral = dict(reply_kind='none', reply_context='other', reply_yes='none', answer_text='', answer_mode='none', date_text='', date_kind='none', time_text='', amount_text='', product_scope='', hardship_present='no')
    ready = str(vars.get('reply_ready', 'idle')) == 'ready'
    e = dict((k, str(vars.get(k, v))) for k, v in neutral.items())
    if ready:
        vars['reply_ready'] = 'idle'
        for k, v in neutral.items():
            vars[k] = v
    history = str(vars.get('system.conversation', ''))
    speeches = re.findall(r'(?ims)^(?:AGENT|ASSISTANT):\s*(.*?)(?=^(?:USER|CALLER|AGENT|ASSISTANT):|\Z)', history)
    agent_history = '\n'.join(speeches)
    asks = len(re.findall(r'am i speaking with', agent_history, re.I))
    opening = 'I am a digital assistant calling from Freya Bank, and this call is recorded.'
    prefix = opening + ' ' if ready and entry_phase == 'name' and opening.lower() not in agent_history.lower() else ''
    if ready and not s['close_attempted']:
        kind = e['reply_kind'] if e['reply_kind'] not in ['', 'none'] else 'nonanswer'
        yes = e['reply_yes']
        if s['held_proposal'] and e['product_scope']:
            held = s['held_proposal']
            for k in ['amount_text', 'date_text']:
                if not e[k]:
                    e[k] = held.get(k, '')
            if e['date_kind'] in ['', 'none']:
                e['date_kind'] = held.get('date_kind', 'none')
            s['held_proposal'] = dict()
        proposal = bool(e['date_text'] or e['amount_text'])
        handled = False
        if kind == 'ai':
            prefix += "I am Freya Bank's digital assistant. "
        elif kind == 'scam':
            prefix += "You can verify this call by phoning Freya Bank's customer service number. "
        elif kind == 'other_question':
            prefix += 'I do not have that information. '
        if kind == 'wrong_number' and not s['verified']:
            end('not_reached', 'wrong_number')
            handled = True
        elif kind == 'deceased' and not s['verified']:
            end('not_reached', 'deceased', 'I am sorry for your loss.')
            handled = True
        elif kind == 'third_party' and not s['verified']:
            s['phase'] = 'callback'
            s['say'] = 'When can ' + str(vars.get('title', '')) + ' ' + str(vars.get('last_name', '')) + ' be reached?'
            handled = True
        elif kind == 'human':
            if s['human_asked']:
                transfer('general')
            else:
                s['human_asked'] = True
                s['resume_phase'] = s['phase']
